head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[radio > M > removeAll]<br/>컴포넌트의 전체 아이템을 제거합니다.",
    "validation" : [        
        "컴포넌트의 전체 아이템을 제거합니다.",
        "DataCollection 바인딩으로 아이템이 정의된 경우 제거된 아이템은 DataCollection 에 반영되지 않습니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // target 생성    
    $c.gcm.createBasicRadio('');
}



scwin.btn_getDataList_onclick = function (e) {
	// let rsData  = dlt_ref.getAllJSON();
    let rsData = gdl_radio.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("label 값 : " + rsData[i].label);
    }
};



scwin.btn_removeAll_onclick = function (e) {  
    target1.removeAll();   

    wf_body_bottom.getObj("scwin").setReturnValue("getItemCount : " + target1.getItemCount());
};
